(async () => {
  const root = document.querySelector('[data-window-gallery]');
  const log = [];
  const origErr = console.error;
  console.error = function (...a) { log.push(a.map(String).join(' ').slice(0, 300)); origErr.apply(console, a); };
  const origWarn = console.warn;
  window.addEventListener('error', e => log.push('window.error: ' + e.message), true);
  window.addEventListener('unhandledrejection', e => log.push('rejection: ' + String(e.reason).slice(0, 200)));
  root.scrollIntoView();
  await new Promise(r => setTimeout(r, 7000));
  console.error = origErr;
  return {cls: root.className, log, err: window.__wgError || null,
          swatches: root.querySelectorAll('.wg__swatch').length, canvas: !!root.querySelector('canvas')};
})()
